const fs = require('fs');
const path = require('path');

// 将边界值统一转成去除首尾空白的字符串。
const safeString = (value) => {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
};

// 读取单个通知记录；坏文件由扫描器跳过，不能阻断整个重试批次。
const readJson = (filePath) => {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch {
    return null;
  }
};

// 按名称倒序列出直接子目录，优先访问最新的年月分区。
const listDirectoriesNewestFirst = (dirPath, namePattern) => {
  if (!fs.existsSync(dirPath)) {
    return [];
  }
  return fs.readdirSync(dirPath, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && namePattern.test(entry.name))
    .map((entry) => entry.name)
    .sort()
    .reverse();
};

// 按时间前缀倒序列出单月 JSON，避免为全部历史文件执行 stat 和全局排序。
const listJsonFilesNewestFirst = (dirPath) => fs.readdirSync(dirPath, { withFileTypes: true })
  .filter((entry) => entry.isFile() && entry.name.endsWith('.json'))
  .map((entry) => entry.name)
  .sort()
  .reverse();

const now = new Date();
const root = path.resolve('/home/node/.n8n-files/feishu_notify_runs');
const batchLimit = Math.max(1, Math.min(50, Number($env.FEISHU_NOTIFY_RETRY_BATCH_LIMIT || 10) || 10));
const scanLimit = Math.max(
  batchLimit,
  Math.min(5000, Number($env.FEISHU_NOTIFY_RETRY_SCAN_LIMIT || 500) || 500)
);
const webhookConfigured = Boolean(safeString($env.FEISHU_WEBHOOK_URL));
const appConfigured = Boolean(safeString($env.FEISHU_APP_NOTIFY_URL));
if (!webhookConfigured && !appConfigured) {
  return [];
}

const candidates = [];
let scannedFileCount = 0;

// 新失败记录必定位于最近分区；限制单轮读取量，避免冷启动时拖死共享 Task Runner。
scanFiles:
for (const year of listDirectoriesNewestFirst(root, /^\d{4}$/)) {
  const yearPath = path.join(root, year);
  for (const month of listDirectoriesNewestFirst(yearPath, /^\d{2}$/)) {
    const monthPath = path.join(yearPath, month);
    for (const fileName of listJsonFilesNewestFirst(monthPath)) {
      if (scannedFileCount >= scanLimit || candidates.length >= batchLimit) {
        break scanFiles;
      }
      scannedFileCount += 1;
      const filePath = path.join(monthPath, fileName);
      const record = readJson(filePath);
      if (!record || typeof record !== 'object') {
        continue;
      }
      if (safeString(record.status) !== 'failed') {
        continue;
      }
      if (record.retryable === false) {
        continue;
      }
      if (!record.request_body || typeof record.request_body !== 'object') {
        continue;
      }
      const deliveryMode = safeString(record.delivery_mode || 'webhook') || 'webhook';
      if (deliveryMode === 'feishu_app' && !appConfigured) {
        continue;
      }
      if (deliveryMode !== 'feishu_app' && !webhookConfigured) {
        continue;
      }
      const retryCount = Number(record.retry_count || 0) || 0;
      const maxRetries = Number(record.max_retries || 10) || 10;
      if (retryCount >= maxRetries) {
        continue;
      }
      const nextRetryAt = safeString(record.next_retry_at || '');
      if (nextRetryAt) {
        const parsedNextRetryAt = new Date(nextRetryAt);
        if (!Number.isNaN(parsedNextRetryAt.getTime()) && parsedNextRetryAt > now) {
          continue;
        }
      }
      const relativePath = path.relative(root, filePath).split(path.sep).join('/');
      candidates.push({
        json: {
          retry_record: record,
          retry_record_path: filePath,
          retry_record_relative_path: 'feishu_notify_runs/' + relativePath,
          retry_delivery_mode: deliveryMode,
          retry_attempted_at: now.toISOString(),
          retry_count_before: retryCount,
          retry_scan: {
            scanned_file_count: scannedFileCount,
            scan_limit: scanLimit
          }
        }
      });
    }
  }
}

return candidates;

const fs = require('fs');

const safeString = (value) => {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
};

const isRetryableFeishuFailure = (message = '', code = '') => {
  const normalized = String(message || '').toLowerCase();
  const transientTokens = [
    'eai_again',
    'enotfound',
    'etimedout',
    'econnreset',
    'econnrefused',
    'socket hang up',
    'network error',
    'timeout'
  ];
  if (transientTokens.some((token) => normalized.includes(token))) {
    return true;
  }
  const numericCode = Number(code);
  return Number.isFinite(numericCode) && numericCode >= 500;
};

const source = $('Scan Failed Feishu Runs').item.json || {};
const record = source.retry_record && typeof source.retry_record === 'object'
  ? source.retry_record
  : {};
const recordPath = safeString(source.retry_record_path || '');
if (!recordPath) {
  throw new Error('10_feishu_notify_retry requires retry_record_path');
}

const response = $json && typeof $json === 'object' ? $json : {};
const error = typeof response.error === 'string'
  ? response.error.trim()
  : response.error && typeof response.error.message === 'string'
    ? response.error.message.trim()
    : '';
const responseCode = response.StatusCode ?? response.code;
const numericResponseCode = Number(responseCode);
const hasNonZeroResponseCode = responseCode !== undefined && Number.isFinite(numericResponseCode) && numericResponseCode !== 0;
const failed = Boolean(error) || hasNonZeroResponseCode;
const now = new Date();
const attemptedAt = safeString(source.retry_attempted_at || '') || now.toISOString();
const previousRetryCount = Number(record.retry_count || 0) || 0;
const retryCount = previousRetryCount + 1;
const maxRetries = Number(record.max_retries || 10) || 10;
const failureMessage = failed ? (error || 'feishu dispatch returned non-zero code ' + responseCode) : '';
const canRetryAgain = failed && retryCount < maxRetries && isRetryableFeishuFailure(failureMessage, responseCode);
const delayMinutes = canRetryAgain
  ? Math.min(60, Math.max(5, 5 * Math.pow(2, Math.min(retryCount - 1, 4))))
  : 0;
const nextRetryAt = canRetryAgain
  ? new Date(now.getTime() + delayMinutes * 60 * 1000).toISOString()
  : '';
const history = Array.isArray(record.retry_history) ? record.retry_history : [];
const updatedRecord = {
  ...record,
  status: failed ? 'failed' : 'sent',
  retryable: canRetryAgain,
  retry_count: retryCount,
  max_retries: maxRetries,
  last_retry_at: attemptedAt,
  next_retry_at: nextRetryAt,
  sent_at: failed ? safeString(record.sent_at || '') : now.toISOString(),
  updated_at: now.toISOString(),
  retry_exhausted_at: failed && !canRetryAgain ? now.toISOString() : safeString(record.retry_exhausted_at || ''),
  error: failureMessage,
  response: failed ? null : response,
  retry_history: [
    ...history,
    {
      attempted_at: attemptedAt,
      finished_at: now.toISOString(),
      delivery_mode: safeString(record.delivery_mode || 'webhook') || 'webhook',
      status: failed ? 'failed' : 'sent',
      error: failureMessage,
      response: failed ? null : response
    }
  ].slice(-20)
};

fs.writeFileSync(recordPath, JSON.stringify(updatedRecord, null, 2), 'utf8');

return {
  json: {
    ok: !failed,
    status: updatedRecord.status,
    retryable: updatedRecord.retryable,
    retry_count: retryCount,
    max_retries: maxRetries,
    next_retry_at: nextRetryAt,
    retry_record_path: safeString(source.retry_record_relative_path || recordPath),
    delivery_mode: safeString(record.delivery_mode || 'webhook') || 'webhook',
    item_id: safeString(record.item_id || ''),
    title: safeString(record.title || ''),
    vault_path: safeString(record.vault_path || ''),
    error: failureMessage,
    response: failed ? null : response
  }
};

return {
  json: {
    ...$json,
    retry_workflow: '10 Feishu Notify Retry',
    finished_at: new Date().toISOString()
  }
};
